-- REVIEW ONLY. Not applied. Generated by `supabase migration new` (CLI 2.54.11).
-- Requires the reviewed 20261026.1 backend foundation and a private, unexposed
-- igotu_backend_private schema. Obtain separate approval and isolated test proof.
-- Does not alter public.users, complete_basic_profile, or existing grants/policies.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
DO $review_gate$
BEGIN
 IF current_setting('igotu.profile_media.reviewed',true) IS DISTINCT FROM 'true'
 OR current_user <> 'postgres' THEN RAISE EXCEPTION 'Review-only migration: explicit reviewed deployment approval required.'; END IF;
 IF to_regprocedure('igotu_backend_private.require_workspace(text)') IS NULL
 OR to_regprocedure('igotu_backend_private.require_read_committed()') IS NULL THEN
 RAISE EXCEPTION 'Reviewed backend foundation is required.'; END IF;
 IF EXISTS(SELECT 1 FROM regexp_split_to_table(coalesce(current_setting('pgrst.db_schemas',true),''),',') AS x(name)
 WHERE trim(both '"' FROM btrim(x.name))='igotu_backend_private') THEN RAISE EXCEPTION 'Private schema must not be exposed.'; END IF;
 -- Absence in this setting is not proof: verify effective API schemas manually.
 IF NOT coalesce((SELECT relrowsecurity FROM pg_class WHERE oid=to_regclass('storage.objects')),false) THEN RAISE EXCEPTION 'Storage RLS required.'; END IF;
 IF EXISTS(SELECT 1 FROM storage.buckets WHERE id='client-profile-media') THEN RAISE EXCEPTION 'Unexpected existing bucket: inspect before applying.'; END IF;
END $review_gate$;
CREATE TABLE public.client_profile_media (
 user_id uuid PRIMARY KEY REFERENCES public.users(id) ON DELETE CASCADE,
 avatar_mode text NOT NULL DEFAULT 'initial' CHECK(avatar_mode IN ('initial','template','upload')),
 avatar_value text,
 banner_mode text NOT NULL DEFAULT 'default' CHECK(banner_mode IN ('default','template','upload','custom')),
 banner_value text,
 banner_design jsonb,
 version bigint NOT NULL DEFAULT 0 CHECK(version>=0),
 last_operation_id uuid,
 updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.client_profile_media ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.client_profile_media FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.client_profile_media TO authenticated;
CREATE POLICY client_profile_media_owner_read ON public.client_profile_media FOR SELECT TO authenticated
 USING(user_id=(SELECT auth.uid()) AND (SELECT igotu_backend_private.workspace('client')));
-- No direct INSERT/UPDATE/DELETE grants; settings can only change through RPC.
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
 VALUES('client-profile-media','client-profile-media',false,5242880,ARRAY['image/webp']);
CREATE FUNCTION igotu_backend_private.profile_media_path_allowed(object_name text, object_owner text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=''
AS $$ SELECT auth.uid() IS NOT NULL AND object_owner=auth.uid()::text
 AND igotu_backend_private.workspace('client') AND object_name ~ ('^'||auth.uid()::text||'/(avatar|banner)/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.webp$') $$;
REVOKE ALL ON FUNCTION igotu_backend_private.profile_media_path_allowed(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION igotu_backend_private.profile_media_path_allowed(text,text) TO authenticated;
-- Restrictive boundary defeats any broader pre-existing permissive bucket policy.
CREATE POLICY client_profile_media_boundary ON storage.objects AS RESTRICTIVE FOR ALL TO anon,authenticated
 USING(bucket_id<>'client-profile-media' OR igotu_backend_private.profile_media_path_allowed(name,owner_id))
 WITH CHECK(bucket_id<>'client-profile-media' OR igotu_backend_private.profile_media_path_allowed(name,owner_id));
CREATE POLICY client_profile_media_read ON storage.objects FOR SELECT TO authenticated
 USING(bucket_id='client-profile-media' AND igotu_backend_private.profile_media_path_allowed(name,owner_id));
CREATE POLICY client_profile_media_insert ON storage.objects FOR INSERT TO authenticated
 WITH CHECK(bucket_id='client-profile-media' AND igotu_backend_private.profile_media_path_allowed(name,owner_id));
-- No overwrites, even if an existing broad UPDATE policy would otherwise allow it.
CREATE POLICY client_profile_media_no_update ON storage.objects AS RESTRICTIVE FOR UPDATE TO anon,authenticated
 USING(bucket_id<>'client-profile-media') WITH CHECK(bucket_id<>'client-profile-media');
CREATE POLICY client_profile_media_delete_boundary ON storage.objects AS RESTRICTIVE FOR DELETE TO anon,authenticated
 USING(bucket_id<>'client-profile-media' OR NOT EXISTS(SELECT 1 FROM public.client_profile_media m
 WHERE m.user_id=(SELECT auth.uid()) AND (m.avatar_value=name OR m.banner_value=name)));
CREATE POLICY client_profile_media_delete_orphan ON storage.objects FOR DELETE TO authenticated
 USING(bucket_id='client-profile-media' AND igotu_backend_private.profile_media_path_allowed(name,owner_id)
 AND NOT EXISTS(SELECT 1 FROM public.client_profile_media m WHERE m.user_id=(SELECT auth.uid()) AND (m.avatar_value=name OR m.banner_value=name)));
CREATE FUNCTION igotu_backend_private.get_client_profile_media() RETURNS jsonb
 LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=''
AS $$ DECLARE actor uuid; result jsonb; BEGIN
 actor:=igotu_backend_private.require_workspace('client');
 SELECT to_jsonb(m) INTO result FROM public.client_profile_media m WHERE m.user_id=actor;
 RETURN coalesce(result,jsonb_build_object('user_id',actor,'avatar_mode','initial','avatar_value',NULL,'banner_mode','default','banner_value',NULL,'banner_design',NULL,'version',0,'last_operation_id',NULL));
END $$;
CREATE FUNCTION igotu_backend_private.save_client_profile_media(p_expected_version bigint,p_operation_id uuid,p_settings jsonb) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path=''
AS $$ DECLARE actor uuid; current_row public.client_profile_media%rowtype; a text; b text; av text; bv text; d jsonb; k text; new_path text; old_path text; media_size bigint; BEGIN
 PERFORM igotu_backend_private.require_read_committed();
 actor:=igotu_backend_private.require_workspace('client');
 -- All writers take the same row lock. A first insert can only create defaults.
 INSERT INTO public.client_profile_media(user_id) VALUES(actor) ON CONFLICT(user_id) DO NOTHING;
 SELECT * INTO current_row FROM public.client_profile_media WHERE user_id=actor FOR UPDATE;
 IF p_operation_id IS NULL OR p_expected_version IS NULL OR p_expected_version<0 THEN RAISE EXCEPTION 'Invalid operation.'; END IF;
 IF current_row.last_operation_id=p_operation_id THEN RETURN to_jsonb(current_row); END IF;
 IF current_row.version<>p_expected_version THEN RAISE EXCEPTION 'Appearance version conflict.' USING ERRCODE='40001'; END IF;
 IF jsonb_typeof(p_settings) IS DISTINCT FROM 'object' OR
 (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_settings) key) IS DISTINCT FROM ARRAY['avatar_mode','avatar_value','banner_design','banner_mode','banner_value']::text[]
 THEN RAISE EXCEPTION 'Invalid settings shape.'; END IF;
 a:=p_settings->>'avatar_mode';b:=p_settings->>'banner_mode';av:=p_settings->>'avatar_value';bv:=p_settings->>'banner_value';d:=p_settings->'banner_design';
 IF a IS NULL OR b IS NULL OR a NOT IN ('initial','template','upload') OR b NOT IN ('default','template','upload','custom') THEN RAISE EXCEPTION 'Invalid appearance mode.'; END IF;
 IF (a='initial' AND av IS NOT NULL) OR (a='template' AND (av IS NULL OR av NOT IN ('avatar-01','avatar-02','avatar-03','avatar-04','avatar-05','avatar-06','avatar-07','avatar-08','avatar-09','avatar-10','avatar-11','avatar-12')))
 OR (b IN ('default','custom') AND bv IS NOT NULL) OR (b='template' AND (bv IS NULL OR bv NOT IN ('banner-01','banner-02','banner-03','banner-04','banner-05','banner-06','banner-07','banner-08')))
 THEN RAISE EXCEPTION 'Invalid template.'; END IF;
 IF b='custom' THEN
  IF jsonb_typeof(d) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(d) key) IS DISTINCT FROM ARRAY['accent','color','pattern']::text[]
  OR NOT(d ?& ARRAY['color','accent','pattern']) OR (d->>'color') NOT IN ('forest','mint','sage','cream','deep') OR (d->>'accent') NOT IN ('forest','mint','sage','cream','deep')
  OR (d->>'pattern') NOT IN ('solid','gradient','circles','diagonal') OR jsonb_typeof(d->'color')<>'string' OR jsonb_typeof(d->'accent')<>'string' OR jsonb_typeof(d->'pattern')<>'string'
  THEN RAISE EXCEPTION 'Invalid banner design.'; END IF;
 ELSIF d IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Unexpected design.'; END IF;
 FOREACH k IN ARRAY ARRAY['avatar','banner'] LOOP
  IF p_settings->>(k||'_mode')='upload' THEN
   new_path:=p_settings->>(k||'_value');old_path:=CASE WHEN k='avatar' THEN current_row.avatar_value ELSE current_row.banner_value END;
   -- New references must use this operation's immutable path. Previously retired
   -- paths cannot be re-adopted by another operation, making post-ACK cleanup safe.
   IF new_path IS NULL OR (new_path IS DISTINCT FROM old_path AND new_path<>actor::text||'/'||k||'/'||p_operation_id::text||'.webp')
   OR NOT igotu_backend_private.profile_media_path_allowed(new_path,actor::text) THEN RAISE EXCEPTION 'Invalid owner-scoped media path.'; END IF;
   SELECT (o.metadata->>'size')::bigint INTO media_size FROM storage.objects o WHERE o.bucket_id='client-profile-media' AND o.name=new_path AND o.owner_id=actor::text AND o.metadata->>'mimetype'='image/webp';
   IF media_size IS NULL OR media_size<=0 OR media_size>(CASE WHEN k='avatar' THEN 2097152 ELSE 5242880 END) THEN RAISE EXCEPTION 'Uploaded media is missing or exceeds its limit.'; END IF;
  END IF;
 END LOOP;
 UPDATE public.client_profile_media SET avatar_mode=a,avatar_value=av,banner_mode=b,banner_value=bv,banner_design=CASE WHEN b='custom' THEN d ELSE NULL END,
 version=current_row.version+1,last_operation_id=p_operation_id,updated_at=now() WHERE user_id=actor RETURNING * INTO current_row;
 RETURN to_jsonb(current_row);
END $$;
REVOKE ALL ON FUNCTION igotu_backend_private.get_client_profile_media(),igotu_backend_private.save_client_profile_media(bigint,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION igotu_backend_private.get_client_profile_media(),igotu_backend_private.save_client_profile_media(bigint,uuid,jsonb) TO authenticated;
CREATE FUNCTION public.get_client_profile_media() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=''
 AS $$ SELECT igotu_backend_private.get_client_profile_media() $$;
CREATE FUNCTION public.save_client_profile_media(p_expected_version bigint,p_operation_id uuid,p_settings jsonb) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=''
 AS $$ SELECT igotu_backend_private.save_client_profile_media(p_expected_version,p_operation_id,p_settings) $$;
REVOKE ALL ON FUNCTION public.get_client_profile_media(),public.save_client_profile_media(bigint,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_client_profile_media(),public.save_client_profile_media(bigint,uuid,jsonb) TO authenticated;
COMMIT;
